import React, { useState, useEffect } from 'react';
import Modal, { ModalHeader } from '../components/Modal';
import Calendar from '../components/Calendar';
import api from '../services/api';
import { useAuth } from '../context/AuthContext';

function Stars({ n }) {
  const v = parseFloat(n) || 0;
  return (
    <span>
      <span style={{ color: '#f59e0b' }}>{'★'.repeat(Math.floor(v))}</span>
      <span style={{ color: 'var(--text2)', fontSize: '.8rem' }}> {v.toFixed(1)}</span>
    </span>
  );
}

export default function ProfModal({ prof, onClose }) {
  const { user } = useAuth();

  const [tab, setTab] = useState('profil');
  const [avis, setAvis] = useState([]);
  const [dispos, setDispos] = useState([]);

  const [step, setStep] = useState(null);
  const [selectedDispo, setSelectedDispo] = useState(null);
  const [modeChoisi, setModeChoisi] = useState(null);
  const [notes, setNotes] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [reservationFaite, setReservationFaite] = useState(null);

  // 🔥 NEW
  const [timeLeft, setTimeLeft] = useState('');
  const [canJoin, setCanJoin] = useState(false);
  const [notified, setNotified] = useState(false);

  const profId = prof.prof_id || prof.id;
  const profMode = prof.mode_enseignement || 'presentiel';
  const profNom = prof.user_nom || prof.nom || 'Professeur';

  useEffect(() => {
    if (tab === 'avis') {
      api.get(`/api/avis/professeur/${profId}`)
        .then(r => setAvis(r.data))
        .catch(() => setAvis([]));
    }
    if (tab === 'calendrier' || step === 'choix_dispo') {
      api.get(`/api/professeurs/${profId}/disponibilites`)
        .then(r => setDispos(r.data ?? []))
        .catch(() => setDispos([]));
    }
  }, [tab, step, profId]);

  // 🔥 TIMER + NOTIFICATION
  useEffect(() => {
    if (step === 'confirmation' && reservationFaite) {

      if (Notification.permission !== "granted") {
        Notification.requestPermission();
      }

      const interval = setInterval(() => {
        const dateTime = new Date(
          reservationFaite.date_cours + 'T' + reservationFaite.heure_debut
        ).getTime();

        const now = new Date().getTime();
        const diff = dateTime - now;

        if (diff <= 0) {
          setCanJoin(true);
          setTimeLeft('Le cours a commencé');
          return;
        }

        if (diff <= 10 * 60 * 1000 && !notified) {
          new Notification('📚 Cours bientôt !', {
            body: 'Votre cours commence dans 10 minutes',
          });
          setNotified(true);
        }

        const h = Math.floor(diff / (1000 * 60 * 60));
        const m = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
        const s = Math.floor((diff % (1000 * 60)) / 1000);

        setTimeLeft(`${h}h ${m}m ${s}s`);
      }, 1000);

      return () => clearInterval(interval);
    }
  }, [step, reservationFaite, notified]);

  const formatDate = (str) =>
    str ? new Date(str + 'T00:00:00').toLocaleDateString('fr-FR', {
      weekday: 'long', day: 'numeric', month: 'long'
    }) : '';

  const getModeInfo = (mode) => {
    if (mode === 'en_ligne')
      return { icon: '🌐', label: 'En ligne', color: '#38bdf8', bg: 'rgba(56,189,248,0.12)' };
    return { icon: '🏫', label: 'Présentiel', color: '#43e97b', bg: 'rgba(67,233,123,0.12)' };
  };

  const handleReserver = async () => {
    if (!selectedDispo) return;
    setSubmitting(true);
    try {
      const res = await api.post('/api/reservations/', {
        prof_id: profId,
        disponibilite_id: selectedDispo.id,
        date_cours: selectedDispo.date_specifique,
        heure_debut: selectedDispo.heure_debut,
        heure_fin: selectedDispo.heure_fin,
        mode_seance: profMode,
        notes_etudiant: notes,
      });
      setReservationFaite(res.data);
      setStep('confirmation');
    } catch (e) {
      alert('Erreur');
    } finally {
      setSubmitting(false);
    }
  };

  if (step === 'confirmation' && reservationFaite) {
    const mode = reservationFaite.mode_seance;

    return (
      <Modal onClose={onClose} maxWidth={500}>
        <div style={{ textAlign: 'center' }}>
          <h2>🎉 Réservation envoyée</h2>

          {mode === 'en_ligne' && reservationFaite.lien_meet && (
            <div style={{ padding: 20 }}>

              <div>⏳ {timeLeft}</div>

              {!canJoin && <div>🔒 Accès bloqué jusqu’à l’heure</div>}

              <a
                href={canJoin ? reservationFaite.lien_meet : '#'}
                onClick={(e) => { if (!canJoin) e.preventDefault(); }}
                target="_blank"
                rel="noreferrer"
                style={{
                  display: 'block',
                  margin: 10,
                  padding: 10,
                  background: canJoin ? '#38bdf8' : '#ccc'
                }}
              >
                📹 Rejoindre Meet
              </a>

              <button onClick={() => {
                navigator.clipboard.writeText(reservationFaite.lien_meet);
                alert('Copié');
              }}>
                📋 Copier
              </button>

              {canJoin && (
                <button onClick={async () => {
                  await api.post(`/api/reservations/${reservationFaite.id}/presence`);
                  alert('Présence OK');
                }}>
                  ✅ Présence
                </button>
              )}

            </div>
          )}

          <button onClick={onClose}>Fermer</button>
        </div>
      </Modal>
    );
  }

  return (
    <Modal onClose={onClose}>
      <ModalHeader onClose={onClose} />
      <button onClick={() => setStep('choix_dispo')}>
        Réserver
      </button>

      {step === 'choix_dispo' && (
        <button onClick={handleReserver}>
          Confirmer
        </button>
      )}
    </Modal>
  );
}
